function initReviewsSwiper(e){if("undefined"==typeof Swiper)return;const i=e.closest(".reviews-section"),r=e.querySelectorAll(".swiper-slide").length;new Swiper(e,{slidesPerView:"auto",centeredSlides:!0,spaceBetween:60,loop:r>1,speed:500,grabCursor:!0,slideToClickedSlide:!0,keyboard:{enabled:!0},navigation:i?{nextEl:i.querySelector(".reviews-section__nav--next"),prevEl:i.querySelector(".reviews-section__nav--prev")}:void 0})}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".reviews-section__swiper").forEach(initReviewsSwiper)});